import assert from 'node:assert/strict';

export async function runMotionDuplicateSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.im-hov[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent})));}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');assert.equal(await page.$eval('[data-motion-layer="'+id+'"]',n=>n.getAttribute('aria-pressed')),'true');}
  async function duplicate(){const old=(await layers()).map(n=>n.id);await page.click('[data-motion-duplicate]');const id=(await layers()).find(n=>!old.includes(n.id)).id;await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected'),{},id);return id;}
  async function moment(at){const id=await page.$eval('[data-motion-key]',(n,at)=>[...n.options].find(o=>o.textContent===at+'%').value,at);await page.select('[data-motion-key]',id);}
  async function change(selector,value){await page.$eval(selector,(n,v)=>{n.value=String(v);n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function pose(id){return page.evaluate(id=>{const n=document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelector('[data-id="'+id+'"]');return {x:parseFloat(n.style.left),y:parseFloat(n.style.top),w:n.style.width,vars:['x','y','z','rx','ry','scale','rot','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k))};},id);}
  await page.click('.tb-left [data-motion-open]');await frame();assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await page.click('[data-motion-library-tab="elements"]');const original=await layers(),sourceId=original[0].id,headingId=original[4].id;await choose(sourceId);await moment(0);const sourcePose=await pose(sourceId),sourceKeys=await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>n.value));const imageCopy=await duplicate(),copyPose=await pose(imageCopy);assert.equal((await layers()).length,7);assert.equal(copyPose.x,sourcePose.x+3);assert.equal(copyPose.y,sourcePose.y+3);assert.equal(copyPose.w,sourcePose.w);assert.deepEqual(copyPose.vars,sourcePose.vars);assert.deepEqual(await pose(sourceId),sourcePose);assert.ok((await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>n.value))).every(id=>!sourceKeys.includes(id)),'Copy has independent point IDs');
  await change('[data-motion-key-property="z"]',-90);assert.equal((await pose(imageCopy)).vars[2],'-90.00px');assert.equal((await pose(sourceId)).vars[2],'-320.00px');
  await choose(headingId);const f=await frame(),heading=await f.$('[data-id="'+headingId+'"]');await heading.focus();await page.keyboard.press('Enter');await page.keyboard.type('Título original personalizado');const textCopy=await duplicate();assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),'Título original personalizado');assert.equal(await page.$eval('[data-motion-content="7"]',n=>n.value),'Título original personalizado','Duplicating confirms active direct text editing');await change('[data-motion-content="7"]','Texto de la copia');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"]')?.textContent==='Texto de la copia',{},textCopy);assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),'Título original personalizado');
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.equal((await layers()).length,6);await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected')?.textContent==='Texto de la copia',{},textCopy);assert.equal((await layers()).length,8);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(({imageCopy,textCopy,sourceId,headingId})=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),copy:sec().elements.find(e=>e.id===imageCopy),textCopy:sec().elements.find(e=>e.id===textCopy),source:sec().elements.find(e=>e.id===sourceId),heading:sec().elements.find(e=>e.id===headingId),assets:project.assets.images.length,sd:sec().sdEnabled,outside:sec().elements[0],ids:sec().elements.flatMap(e=>[e.id,...(e.sdKeyframes||[]).map(k=>k.id)])}),{imageCopy,textCopy,sourceId,headingId});assert.equal(inserted.assets,before.assets+3,'Copies reuse assets');assert.equal(inserted.sd,false,'Time composition remains independent of Scroll');assert.equal(new Set(inserted.ids).size,inserted.ids.length);assert.equal(inserted.copy.assetId,inserted.source.assetId);assert.equal(inserted.copy.parent,inserted.group.id);assert.equal(inserted.copy.mobile.x,inserted.source.mobile.x+3);assert.equal(inserted.copy.mobile.y,inserted.source.mobile.y+3);assert.equal(inserted.copy.sdKeyframes[0].z,-90);assert.equal(inserted.source.sdKeyframes[0].z,-320);assert.equal(inserted.textCopy.text,'Texto de la copia');assert.equal(inserted.heading.text,'Título original personalizado');assert.equal(inserted.textCopy.mobile.customSize,inserted.heading.mobile.customSize);assert.deepEqual(inserted.outside,before.outside);const strip=ks=>ks.map(({id,...k})=>k),expected=strip(inserted.source.sdKeyframes);expected[0].z=-90;assert.deepEqual(strip(inserted.copy.sdKeyframes),expected);
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await frame();await page.click('[data-motion-library-tab="elements"]');assert.equal((await layers()).length,8);await choose(imageCopy);await moment(0);const savedCopy=await duplicate();assert.equal((await layers()).length,9);await change('[data-motion-key-property="z"]',-40);await page.click('[data-motion-save]');const saved=await page.evaluate(({gid,id})=>({project:JSON.stringify(project),element:sec().elements.find(e=>e.id===id),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length,assets:project.assets.images.length,outside:sec().elements[0],source:sec().elements.find(e=>e.id===id)?.assetId}),{gid:inserted.group.id,id:savedCopy});assert.equal(saved.groups,1);assert.equal(saved.members.length,9,'Save appends new members to the same instance');assert.equal(saved.element.sdKeyframes[0].z,-40);assert.equal(saved.assets,inserted.assets);assert.deepEqual(saved.outside,before.outside);assert.equal(saved.members.find(e=>e.id===imageCopy).sdKeyframes[0].z,-90);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await frame();await page.click('[data-motion-library-tab="elements"]');assert.equal((await layers()).length,9);await choose(savedCopy);await duplicate();assert.equal((await layers()).length,10);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='duplicate-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#duplicate-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.group.id);const exported=await page.evaluate(({gid,id,textCopy})=>{const f=document.querySelector('#duplicate-export');f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].set(0);const root=f.contentDocument.querySelector('[data-id="'+gid+'"]'),n=root.querySelector('[data-id="'+id+'"]');return {images:root.querySelectorAll('.im-hov').length,z:n.style.getPropertyValue('--nw-sd-z'),text:root.querySelector('[data-id="'+textCopy+'"]')?.textContent,decoded:!!n.querySelector('img')?.naturalWidth};},{gid:inserted.group.id,id:savedCopy,textCopy});assert.equal(exported.images,5);assert.equal(exported.z,'-40.00px');assert.equal(exported.text,'Texto de la copia');await page.waitForFunction(id=>document.querySelector('#duplicate-export')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth>0,{},savedCopy);
  console.log('Duplicar Motion Lab: lámina/texto con pose y estilos, nuevos IDs, copias independientes, texto activo, borradores/recursos, insertar/guardar nuevos miembros sin duplicar grupo, elementos externos, cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#duplicate-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
